    <script>
    (function() {
        /* ===== 歌单（随机播放池） ===== */
        var playlist = [
            'https://files.catbox.moe/s7m9h9.mp3',
            'https://files.catbox.moe/7jd3bs.flac',
            'https://files.catbox.moe/ciz3jq.flac',
            'https://files.catbox.moe/chhck1.flac',
            'https://files.catbox.moe/ang1kv.flac',
            'https://files.catbox.moe/h8ing4.flac',
            'https://files.catbox.moe/c8i94x.flac',
            'https://files.catbox.moe/uf1pm4.flac',
            'https://files.catbox.moe/83hmzm.flac'
        ];

        /* 打乱歌单顺序（Fisher-Yates洗牌） */
        function shuffle(arr) {
            var a = arr.slice();
            for (var i = a.length - 1; i > 0; i--) {
                var j = Math.floor(Math.random() * (i + 1));
                var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
            }
            return a;
        }

        var shuffled = shuffle(playlist);
        var currentIndex = 0;
        var audio = new Audio();
        audio.preload = 'metadata';
        audio.volume = 0.6;

        /* DOM元素 */
        var disc = document.getElementById('cc-disc');
        var btnPlay = document.getElementById('cc-btn-play');
        var btnPrev = document.getElementById('cc-btn-prev');
        var btnNext = document.getElementById('cc-btn-next');
        var progressFill = document.getElementById('cc-progress-fill');
        var progressWrapper = document.getElementById('cc-progress-wrapper');
        var timeCurrent = document.getElementById('cc-time-current');
        var timeTotal = document.getElementById('cc-time-total');

        /* 格式化时间 */
        function formatTime(s) {
            if (isNaN(s) || !isFinite(s)) return '0:00';
            var m = Math.floor(s / 60);
            var sec = Math.floor(s % 60);
            return m + ':' + (sec < 10 ? '0' : '') + sec;
        }

        /* 加载并播放指定索引的歌曲 */
        function loadTrack(index) {
            currentIndex = index;
            audio.src = shuffled[currentIndex];
            audio.load();
        }

        function playTrack() {
            audio.play().then(function() {
                btnPlay.textContent = '⏸';
                btnPlay.classList.add('playing');
                disc.classList.add('spinning');
            }).catch(function() {
                /* 浏览器可能阻止自动播放，用户点击后才能播放 */
            });
        }

        function pauseTrack() {
            audio.pause();
            btnPlay.textContent = '▶';
            btnPlay.classList.remove('playing');
            disc.classList.remove('spinning');
        }

        /* 播放/暂停 */
        btnPlay.addEventListener('click', function() {
            if (audio.paused) {
                if (!audio.src || audio.src === '') {
                    loadTrack(0);
                }
                playTrack();
            } else {
                pauseTrack();
            }
        });

        /* 下一首 */
        btnNext.addEventListener('click', function() {
            currentIndex = (currentIndex + 1) % shuffled.length;
            loadTrack(currentIndex);
            playTrack();
        });

        /* 上一首 */
        btnPrev.addEventListener('click', function() {
            currentIndex = (currentIndex - 1 + shuffled.length) % shuffled.length;
            loadTrack(currentIndex);
            playTrack();
        });

        /* 自动下一首 */
        audio.addEventListener('ended', function() {
            currentIndex = (currentIndex + 1) % shuffled.length;
            loadTrack(currentIndex);
            playTrack();
        });

        /* 更新进度条和时间 */
        audio.addEventListener('timeupdate', function() {
            if (audio.duration && isFinite(audio.duration)) {
                var pct = (audio.currentTime / audio.duration) * 100;
                progressFill.style.width = pct + '%';
                timeCurrent.textContent = formatTime(audio.currentTime);
            }
        });

        audio.addEventListener('loadedmetadata', function() {
            timeTotal.textContent = formatTime(audio.duration);
        });

        /* 点击进度条跳转 */
        progressWrapper.addEventListener('click', function(e) {
            if (audio.duration && isFinite(audio.duration)) {
                var rect = progressWrapper.getBoundingClientRect();
                var pct = (e.clientX - rect.left) / rect.width;
                audio.currentTime = pct * audio.duration;
            }
        });

        /* 初始化：预加载第一首但不自动播放 */
        loadTrack(0);
    })();
    </script>

